CREATE TABLE public.clinical_protocols (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, specialty text NOT NULL DEFAULT '', disease text NOT NULL DEFAULT '', keywords text NOT NULL DEFAULT '', issuing_authority text NOT NULL, revision_date date, version text NOT NULL DEFAULT '', source_url text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','verified','outdated')), document_kind text NOT NULL DEFAULT 'clinical' CHECK (document_kind IN ('clinical','methodology')), file_path text, imported_by uuid NOT NULL DEFAULT auth.uid(), verified_by uuid, verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.clinical_protocols TO authenticated; GRANT ALL ON public.clinical_protocols TO service_role;
ALTER TABLE public.clinical_protocols ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Authenticated protocol reads" ON public.clinical_protocols FOR SELECT TO authenticated USING (status = 'verified' OR public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admin protocol management" ON public.clinical_protocols FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.protocol_passages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), protocol_id uuid NOT NULL REFERENCES public.clinical_protocols(id) ON DELETE CASCADE, page integer NOT NULL DEFAULT 1, section text NOT NULL DEFAULT '', content text NOT NULL);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.protocol_passages TO authenticated; GRANT ALL ON public.protocol_passages TO service_role;
ALTER TABLE public.protocol_passages ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Verified passage reads" ON public.protocol_passages FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.clinical_protocols p WHERE p.id=protocol_id AND p.status='verified') OR public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admin passage management" ON public.protocol_passages FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE INDEX protocol_content_search ON public.protocol_passages USING gin(to_tsvector('simple',content));
CREATE FUNCTION public.search_protocol_passages(search_text text) RETURNS TABLE(passage_id uuid,protocol_id uuid,title text,specialty text,source_url text,version text,revision_date date,page integer,section text,content text) LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT c.id,p.id,p.title,p.specialty,p.source_url,p.version,p.revision_date,c.page,c.section,c.content FROM public.protocol_passages c JOIN public.clinical_protocols p ON p.id=c.protocol_id CROSS JOIN websearch_to_tsquery('simple',left(search_text,2000)) q WHERE p.status='verified' AND p.document_kind='clinical' AND to_tsvector('simple',c.content || ' ' || p.title || ' ' || p.specialty || ' ' || p.disease || ' ' || p.keywords) @@ q ORDER BY ts_rank(to_tsvector('simple',c.content),q) DESC LIMIT 5 $$;
GRANT EXECUTE ON FUNCTION public.search_protocol_passages(text) TO authenticated,service_role;
CREATE FUNCTION public.audit_protocol_verification() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN IF NEW.status='verified' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM NEW.status) THEN IF NEW.source_url !~ '^https://' OR trim(NEW.title)='' OR trim(NEW.issuing_authority)='' THEN RAISE EXCEPTION 'Official metadata and HTTPS source are required'; END IF; NEW.verified_by=auth.uid(); NEW.verified_at=now(); END IF; RETURN NEW; END $$;
CREATE TRIGGER protocol_verification BEFORE INSERT OR UPDATE ON public.clinical_protocols FOR EACH ROW EXECUTE FUNCTION public.audit_protocol_verification();
CREATE TABLE public.clinical_drafts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid(),original_analysis jsonb NOT NULL,edited_analysis jsonb,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','rejected','approved')),consultation_id uuid REFERENCES public.consultations(id),created_at timestamptz NOT NULL DEFAULT now(),approved_at timestamptz);
GRANT SELECT,INSERT ON public.clinical_drafts TO authenticated; GRANT ALL ON public.clinical_drafts TO service_role;
ALTER TABLE public.clinical_drafts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own clinician drafts" ON public.clinical_drafts FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE POLICY "Insert unapproved own draft" ON public.clinical_drafts FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='draft' AND approved_at IS NULL AND consultation_id IS NULL AND (public.has_role(auth.uid(),'doctor') OR public.has_role(auth.uid(),'admin')));
ALTER TABLE public.consultations ADD COLUMN document_status text NOT NULL DEFAULT 'legacy',ADD COLUMN approved_at timestamptz,ADD COLUMN clinical_document jsonb,ADD COLUMN protocol_refs jsonb NOT NULL DEFAULT '[]';
CREATE FUNCTION public.review_clinical_draft(draft_id uuid,decision text,edited jsonb,final_record jsonb DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.clinical_drafts; cid uuid; BEGIN IF auth.uid() IS NULL OR NOT(public.has_role(auth.uid(),'doctor') OR public.has_role(auth.uid(),'admin')) THEN RAISE EXCEPTION 'Clinician required'; END IF; SELECT * INTO d FROM public.clinical_drafts WHERE id=draft_id AND user_id=auth.uid() FOR UPDATE; IF NOT FOUND OR d.status<>'draft' THEN RAISE EXCEPTION 'Editable own draft required'; END IF; IF decision='rejected' THEN UPDATE public.clinical_drafts SET status='rejected',edited_analysis=edited WHERE id=draft_id; RETURN NULL; END IF; IF decision<>'approved' OR final_record IS NULL OR trim(coalesce(final_record->>'diagnosis',''))='' THEN RAISE EXCEPTION 'Explicit approval and final diagnosis required'; END IF; INSERT INTO public.consultations(user_id,patient_name,patient_code,transcript,symptoms,diagnosis,chosen_diagnosis,differentials,recommendation,prescriptions,lab_tests,instrumental_tests,family_advice,language,started_at,ended_at,duration_seconds,document_status,approved_at,clinical_document,protocol_refs) VALUES(auth.uid(),coalesce(final_record->>'patient_name',''),coalesce(final_record->>'patient_code',''),coalesce(final_record->>'transcript',''),coalesce(edited->'symptoms','[]'),final_record->>'diagnosis',final_record->>'diagnosis',coalesce(edited->'differentials','[]'),coalesce(edited->>'recommendation',''),coalesce(edited->'prescriptions','[]'),coalesce(edited->'lab_tests','[]'),coalesce(edited->'instrumental_tests','[]'),coalesce(edited->>'family_advice',''),coalesce(final_record->>'language','uz'),(final_record->>'started_at')::timestamptz,now(),(final_record->>'duration_seconds')::integer,'approved',now(),edited,coalesce(d.original_analysis->'protocol_refs','[]')) RETURNING id INTO cid; UPDATE public.clinical_drafts SET status='approved',edited_analysis=edited,consultation_id=cid,approved_at=now() WHERE id=draft_id; RETURN cid; END $$;
REVOKE ALL ON FUNCTION public.review_clinical_draft(uuid,text,jsonb,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.review_clinical_draft(uuid,text,jsonb,jsonb) TO authenticated;
CREATE POLICY "Admin upload protocol files" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='clinical-protocols' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admin delete protocol files" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='clinical-protocols' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "Read authorized protocol files" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='clinical-protocols' AND (public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.clinical_protocols p WHERE p.file_path=name AND p.status='verified')));